file.content:
&-story {
  width: 100%;

  &__inner {
    width: 100%;
    height: 100%;
    margin-top: var(--header-height);
  }

  &__body {
    width: 100%;
  }

  &__content {
    .block {
      padding-bottom: var(--gutter-4xl);

      &.left {
      }

      &.right {
        padding-bottom: var(--gutter-4xl);
        padding-top: var(--gutter-3xl);
        position: relative;
      }

      @include mq(md) {
        width: 100%;
        padding-bottom: var(--gutter-2xl);

        &.left,
        &.right {
          width: 100%;
        }

        &.right {
          padding-top: 0;
          padding-bottom: var(--gutter-2xl);
        }
      }

      .title {
        h4 {
          margin-top: var(--gutter-xs);
        }
      }

      .body {
        margin-top: var(--gutter-md);

        p {
          margin-top: var(--gutter-sm);
        }
      }
    }
  }
}
&-who {
  width: 100%;
  position: relative;

  &__inner {
    min-height: var(--scene-shell-span);
    position: relative;
  }

  &__title {
    .line {
      text-align: center;
    }
  }

  &__body {
    position: sticky;
    top: var(--header-height);
    min-height: calc(100vh - var(--header-height));
    display: flex;
    align-items: center;
    justify-content: center;

