const MAIN_BACKGROUND_POLICIES: readonly SceneBackgroundPolicy<
  MainSceneSectionKey,
  MainTheatreSheetId
>[] = [
  {
    backgroundId: mainBackground,
    defaultState: MAIN_BACKGROUND_DEFAULT_STATE,
    statesBySheetId: MAIN_BACKGROUND_STATES_BY_SHEET_ID,
    transitionRules: MAIN_BACKGROUND_TRANSITION_RULES,
    resetShaderClockOnVariant: "hero",
  },
] as const;

export const scenes = {
  intro: {},
  hero: {},
  story: {
    onProgress: (progress: number): void => {
      if (!mainSceneDomState.storyStatsFired && progress >= STORY_COUNT_TRIGGER) {
        mainSceneDomState.storyStatsFired = true;
        triggerStoryStats();
      }
    },
  },
  who: {
    onProgress: (progress: number): void => {
      syncWhoScene(progress);
    },
    onDispose: (): void => {
      disposeWhoScene();
    },
  },
  whyus: {},
  services: {},
  works: {},
  worksDetail: {
    onProgress: (progress: number): void => {
      syncWorksDetailHead(progress);
    },
    onDispose: (): void => {
      disposeWorksDetailHead();
    },
  },
  worksFinal: {
    onDispose: (): void => {
      _portfolioHoverCleanups.forEach((fn) => fn());
      _portfolioHoverCleanups.length = 0;
    },
  },

