237	export class ScrollSceneRuntime {
238	  private _root: ParentNode | null = null;
239	  private _cleanup: (() => void) | null = null;
240	  private _shellCleanupList: Array<() => void> = [];
241	  private _frameId = 0;
242	  private _isDirty = false;
243	  private _activeSceneKey: string | null = null;
244	  private readonly _progressState = new Map<string, ScrollSceneProgressState>();
245	  private readonly _activationRuntime = new ScrollSceneActivationRuntime(
246	    this._getViewportHeight.bind(this),
247	  );
248	  private readonly _progressRuntime = new ScrollSceneProgressRuntime(
249	    this._getViewportHeight.bind(this),
250	  );
251	
252	  setRoot(root?: ParentNode | null): void {
253	    this._root = root ?? null;
254	  }
255	
256	  start<TSceneKey extends string>(
257	    selectorByScene: Readonly<Partial<Record<TSceneKey, string>>>,
258	    applyProgress: (sceneKey: TSceneKey, progress: number) => void,
259	    optionsByScene?: Readonly<
260	      Partial<Record<TSceneKey, ScrollSceneProgressOptions>>
261	    >,
262	    runtimeOptions?: {
263	      skipInitialSync?: boolean;
264	    },
265	  ): void {
266	    this.dispose();
267	    const sceneElements = this._resolveSceneElements(selectorByScene);
268	    this._setupSceneShells(sceneElements, optionsByScene);
269	
270	    const updateTarget = (): void => {
271	      const activeSceneKey = this._activationRuntime.resolveActiveSceneKey(
272	        sceneElements,
273	        optionsByScene,
274	      );
275	      if (!activeSceneKey) return;
276	      const element = sceneElements.get(activeSceneKey)?.element;
277	      if (!element) return;
278	      const nextTarget = this._progressRuntime.resolveSectionProgress(
279	        element,
280	        optionsByScene?.[activeSceneKey],
281	      );
282	      const now = this._getNow();
283	      const didSceneChange = this._activeSceneKey !== activeSceneKey;
284	      const state = this._resolveProgressState(activeSceneKey, now, nextTarget);
285	      state.target = nextTarget;
286	      if (didSceneChange) {
287	        state.display = nextTarget;
288	      }
289	      state.updatedAt = now;
290	      if (
291	        isDebugSceneKey(activeSceneKey) &&
292	        (didSceneChange ||
293	          shouldLogDebugSceneProgress(
294	            debugTargetLogKeyByScene,
295	            activeSceneKey,
296	            "target",
297	            nextTarget,
298	          ))
299	      ) {
