  backgroundPolicies: MAIN_BACKGROUND_POLICIES,
  introOverlay: MAIN_IS_AUTHOR_MODE ? null : introOverlay,
  orbitControls: {
    enabled: true,
    enableDamping: true,
    dampingFactor: 0.08,
    rotateSpeed: 0.7,
    zoomSpeed: 0.8,
    panSpeed: 0.6,
    minDistance: 0.01,
    maxDistance: 80,
    minPolarAngle: 0.1,
    maxPolarAngle: Math.PI - 0.1,
